(async()=>{
'use strict';
const cash=v=>v==null?'Preço a confirmar':(v/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const clean=s=>(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let catalog;try{const r=await fetch('/data/catalog.json');if(!r.ok)throw Error();catalog=await r.json()}catch{if(document.getElementById('store-content'))document.getElementById('store-content').innerHTML='<p>Não foi possível carregar os produtos. Atualize a página para tentar novamente.</p>';return}
const byId=new Map(catalog.map(p=>[p.id,p]));const byPath=new Map(catalog.map(p=>[p.path.replace(/\/$/,''),p]));
const productUrl=id=>'/produto.html?id='+encodeURIComponent(id);
let cart;let favorites;try{cart=JSON.parse(localStorage.getItem('growth-cart-v1')||'[]');favorites=JSON.parse(localStorage.getItem('growth-favorites-v1')||'[]')}catch{cart=[];favorites=[]}if(!Array.isArray(cart))cart=[];if(!Array.isArray(favorites))favorites=[];cart=cart.filter(x=>byId.has(x.id)&&Number.isInteger(x.quantity)&&x.quantity>0&&Number.isInteger(x.price)&&x.price>0);let returnFocus=null;
function persist(){localStorage.setItem('growth-cart-v1',JSON.stringify(cart));localStorage.setItem('growth-favorites-v1',JSON.stringify(favorites));updateBadges()}
function updateBadges(){const count=cart.reduce((s,i)=>s+i.quantity,0);document.querySelectorAll('button[aria-label^="Abrir meu carrinho"],#mobile-cart').forEach(b=>{b.setAttribute('aria-label','Abrir meu carrinho de compras, '+count+' itens');const badge=b.querySelector('span');if(badge)badge.textContent=count})}
function toast(text){document.querySelector('.store-toast')?.remove();const d=document.createElement('div');d.className='store-toast';d.setAttribute('role','status');d.textContent=text;document.body.append(d);setTimeout(()=>d.remove(),2600)}
function favorite(id){favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];persist();document.querySelectorAll('[data-favorite="'+id+'"]').forEach(b=>{b.classList.toggle('active',favorites.includes(id));b.setAttribute('aria-pressed',String(favorites.includes(id)));b.textContent=favorites.includes(id)?'♥':'♡'});toast(favorites.includes(id)?'Produto salvo nos favoritos':'Produto removido dos favoritos')}
function closeCart(){document.querySelector('.store-cart')?.remove();document.querySelector('.store-overlay')?.remove();document.body.style.overflow='';returnFocus?.focus()}
function openCart(){if(!document.querySelector('.store-cart'))returnFocus=document.activeElement;document.querySelector('.store-cart')?.remove();document.querySelector('.store-overlay')?.remove();const overlay=document.createElement('div');overlay.className='store-overlay';overlay.onclick=closeCart;const panel=document.createElement('section');panel.className='store-cart';panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label','Carrinho de compras');const total=cart.reduce((s,i)=>s+i.price*i.quantity,0);panel.innerHTML='<header><strong>MEU CARRINHO ('+cart.reduce((s,i)=>s+i.quantity,0)+')</strong><button class="cart-close" aria-label="Fechar carrinho">×</button></header><div class="cart-items">'+(cart.length?cart.map((i,n)=>{const p=byId.get(i.id);return '<article class="cart-item"><img src="'+esc(i.image||p.images[0])+'" alt="'+esc(p.name)+'"><div><a href="'+productUrl(p.id)+'">'+esc(p.name)+'</a><p>'+esc(Object.values(i.options).join(' · '))+'</p><strong>'+cash(i.price)+'</strong><div class="cart-item-bottom"><div class="quantity-control"><button aria-label="Diminuir quantidade" data-cart-delta="-1" data-index="'+n+'">−</button><input aria-label="Quantidade de '+esc(p.name)+'" readonly value="'+i.quantity+'"><button aria-label="Aumentar quantidade" data-cart-delta="1" data-index="'+n+'">+</button></div><button class="cart-remove" data-remove="'+n+'">Remover</button></div></div></article>'}).join(''):'<div class="cart-empty"><h2>Seu carrinho está vazio</h2><p>Escolha os seus produtos para começar.</p><a href="/catalogo.html">Ver produtos</a></div>')+'</div><div class="cart-footer"><div class="cart-total"><span>Subtotal</span><span>'+cash(total)+'</span></div><button class="buy-button" '+(!cart.length?'disabled':'')+' data-review>REVISAR CARRINHO</button><small>Pagamento e cálculo de frete estarão disponíveis após a integração da loja. Nenhum pedido será enviado nesta prévia.</small></div>';document.body.append(overlay,panel);document.body.style.overflow='hidden';panel.querySelector('.cart-close').onclick=closeCart;panel.querySelector('.cart-close').focus();panel.querySelectorAll('[data-cart-delta]').forEach(b=>b.onclick=()=>{const i=cart[+b.dataset.index];i.quantity=Math.max(1,Math.min(99,i.quantity+Number(b.dataset.cartDelta)));persist();openCart()});panel.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{cart.splice(+b.dataset.remove,1);persist();openCart()});panel.querySelector('[data-review]').onclick=()=>{location.href='/carrinho.html'};panel.addEventListener('keydown',e=>{if(e.key==='Escape')closeCart();if(e.key==='Tab'){const f=[...panel.querySelectorAll('button:not(:disabled),a,input')];if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus()}}})}
function card(p){return '<article class="store-card"><button class="store-fav '+(favorites.includes(p.id)?'active':'')+'" aria-label="Favoritar '+esc(p.name)+'" aria-pressed="'+favorites.includes(p.id)+'" data-favorite="'+p.id+'">'+(favorites.includes(p.id)?'♥':'♡')+'</button><a href="'+productUrl(p.id)+'"><img loading="lazy" src="'+esc(p.images[0]||'')+'" alt="'+esc(p.name)+'"></a><a href="'+productUrl(p.id)+'" style="color:inherit;text-decoration:none"><h2>'+esc(p.name)+'</h2></a><span class="product-price">'+cash(p.price)+'</span><small>No boleto ou Pix · preço da referência</small><a class="buy-button" href="'+productUrl(p.id)+'">VER PRODUTO</a></article>'}
function wireFavorites(root){root.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=()=>favorite(b.dataset.favorite))}
function routeLink(a){const raw=a.getAttribute('href');if(!raw||raw.startsWith('javascript:'))return null;let url;try{url=new URL(raw,location.origin)}catch{return null}if(!['www.gsuplementos.com.br','gsuplementos.com.br',location.hostname].includes(url.hostname))return null;const path=url.pathname.replace(/\/$/,'');const p=byPath.get(path);if(p)return productUrl(p.id);if(/minha-conta\/lista-desejo/.test(path))return '/favoritos.html';if(!path||path==='/mobile.html')return raw.startsWith('#')?null:'/';if(/\.html$|\/assets\/|\/data\//.test(path))return null;if(raw.startsWith('#'))return null;return '/catalogo.html?categoria='+encodeURIComponent(path)}
document.addEventListener('click',e=>{const cartButton=e.target.closest('button[aria-label^="Abrir meu carrinho"],#mobile-cart');if(cartButton){e.preventDefault();e.stopImmediatePropagation();openCart();return}const fav=e.target.closest('.btFavorito');if(fav){const id=fav.id.replace('favorito-','');if(byId.has(id)){e.preventDefault();e.stopImmediatePropagation();favorite(id);return}}const a=e.target.closest('a');if(a){const target=routeLink(a);if(target){e.preventDefault();e.stopImmediatePropagation();location.href=target}}},true);
document.addEventListener('submit',e=>{const input=e.target.querySelector('input[name="busca"],input[type="search"],input[role="combobox"]');if(input){e.preventDefault();e.stopImmediatePropagation();location.href='/catalogo.html?q='+encodeURIComponent(input.value)}},true);
document.querySelectorAll('a[href]').forEach(a=>{const target=routeLink(a);if(target)a.href=target});
const root=document.getElementById('store-content');const params=new URLSearchParams(location.search);
if(root&&location.pathname==='/produto.html'){
const p=byId.get(params.get('id'));if(!p){root.innerHTML='<h1>Produto não encontrado</h1><a href="/catalogo.html">Voltar ao catálogo</a>';return}document.title=p.name+' | Growth Supplements';const options={};p.groups.forEach(g=>{const o=g.options.find(o=>o.selected&&!o.disabled);if(o)options[g.name]=o.name});let price=p.price;let selectedImage=p.images[0];
root.innerHTML='<nav class="store-crumbs"><a href="/">G SUPLEMENTOS</a><span>›</span><a href="/catalogo.html">'+esc(p.category||'PRODUTOS')+'</a><span>›</span><span>'+esc(p.name)+'</span></nav><div class="product-grid"><div class="product-gallery"><div class="product-thumbs">'+p.images.slice(0,8).map((u,i)=>'<button aria-label="Ver foto '+(i+1)+'" data-image="'+esc(u)+'"><img src="'+esc(u)+'" alt="Foto '+(i+1)+' de '+esc(p.name)+'"></button>').join('')+'</div><div class="product-main-image"><img id="product-main-photo" src="'+esc(p.images[0])+'" alt="'+esc(p.name)+'"></div></div><div class="product-info"><h1>'+esc(p.name)+'</h1>'+(p.tables.length?'<a class="nutrition-link" href="#nutricao">Veja a tabela nutricional</a>':'')+'<div class="product-pricing">'+(p.original&&p.original>p.price?'<div class="old-price">'+cash(p.original)+'</div>':'')+'<div><strong class="product-price" id="product-price">'+cash(price)+'</strong> <span>(Cada) no boleto ou no Pix</span></div><p class="product-payment">Preço observado na loja de referência.</p></div>'+p.groups.map(g=>'<fieldset class="variant-group"><legend>'+esc(g.name)+': <strong data-chosen="'+esc(g.name)+'">'+esc(options[g.name]||'Selecione')+'</strong></legend><div class="variant-options">'+g.options.map(o=>'<button class="variant-option" data-group="'+esc(g.name)+'" data-option="'+esc(o.name)+'" '+(o.disabled?'disabled':'')+' aria-pressed="'+(options[g.name]===o.name)+'">'+(o.images?.[0]?'<img alt="" src="'+esc(o.images[0])+'">':'')+esc(o.name)+(o.price?'<strong>'+cash(o.price)+'</strong>':'')+'</button>').join('')+'</div></fieldset>').join('')+'<div class="quantity-buy"><div class="quantity-control"><button id="quantity-minus" aria-label="Diminuir quantidade">−</button><input id="product-quantity" type="number" min="1" max="99" value="1" aria-label="Quantidade"><button id="quantity-plus" aria-label="Aumentar quantidade">+</button></div><button id="product-buy" class="buy-button" '+(!price||p.variantPending||p.status==='pending'?'disabled':'')+'>COMPRAR</button></div><p class="product-error" role="alert" id="product-error"></p><p class="product-message">'+(p.status==='pending'||p.variantPending?'As opções deste produto ainda estão sendo conferidas. A compra será habilitada após a conferência.':'Adicione ao carrinho para revisar os produtos e suas opções.')+'</p><button class="cart-remove" id="product-favorite">'+(favorites.includes(p.id)?'♥ Salvo nos favoritos':'♡ Adicionar aos favoritos')+'</button></div></div><section class="product-desc"><h2>Sobre '+esc(p.name)+'</h2>'+(p.description?'<div class="product-description-copy">'+esc(p.description)+'</div>':'<p>'+(p.status==='pending'?'As informações completas deste produto ainda estão sendo importadas.':'As informações detalhadas e a tabela nutricional ainda estão sendo conferidas.')+'</p>')+'</section>'+(p.tables.length?'<section class="product-desc" id="nutricao"><h2>Tabela nutricional</h2>'+p.tables.map(rows=>'<table class="nutrition-table">'+rows.map(row=>'<tr>'+row.map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')+'</table>').join('')+'</section>':'')+'<section class="product-desc"><h2>Você também pode gostar</h2><div class="store-products">'+catalog.filter(x=>x.id!==p.id&&x.category===p.category).slice(0,4).map(card).join('')+'</div></section>';
root.querySelectorAll('[data-image]').forEach(b=>b.onclick=()=>{selectedImage=b.dataset.image;document.getElementById('product-main-photo').src=selectedImage});const quantity=document.getElementById('product-quantity');const clamp=()=>quantity.value=String(Math.max(1,Math.min(99,parseInt(quantity.value)||1)));quantity.onchange=clamp;document.getElementById('quantity-minus').onclick=()=>{quantity.value=Number(quantity.value)-1;clamp()};document.getElementById('quantity-plus').onclick=()=>{quantity.value=Number(quantity.value)+1;clamp()};root.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{options[b.dataset.group]=b.dataset.option;const g=p.groups.find(g=>g.name===b.dataset.group);const o=g.options.find(o=>o.name===b.dataset.option);if(o.price){price=o.price;document.getElementById('product-price').textContent=cash(price)}root.querySelectorAll('[data-option]').forEach(x=>x.setAttribute('aria-pressed',String(options[x.dataset.group]===x.dataset.option)));root.querySelectorAll('[data-chosen]').forEach(x=>x.textContent=options[x.dataset.chosen]||'Selecione');document.getElementById('product-error').textContent=''});
document.getElementById('product-buy').onclick=()=>{const missing=p.groups.find(g=>!options[g.name]);if(missing){document.getElementById('product-error').textContent='Selecione '+missing.name.toLowerCase()+' antes de adicionar ao carrinho.';return}clamp();const key=p.id+'|'+JSON.stringify(options);const row=cart.find(x=>x.key===key);if(row)row.quantity=Math.min(99,row.quantity+Number(quantity.value));else cart.push({key,id:p.id,options:{...options},quantity:Number(quantity.value),price,image:selectedImage});persist();openCart()};document.getElementById('product-favorite').onclick=()=>{favorite(p.id);document.getElementById('product-favorite').textContent=favorites.includes(p.id)?'♥ Salvo nos favoritos':'♡ Adicionar aos favoritos'};wireFavorites(root);
}else if(root&&location.pathname==='/carrinho.html'){
root.innerHTML='<h1>Meu carrinho</h1><div class="store-notice">Revise os itens e as variações escolhidas. O pagamento será disponibilizado após a integração do gateway. Nenhuma cobrança ou pedido real será gerado nesta prévia.</div><div class="store-products">'+cart.map(i=>{const p=byId.get(i.id);return '<article class="store-card"><img src="'+esc(i.image||p.images[0])+'" alt="'+esc(p.name)+'"><h2>'+esc(p.name)+'</h2><p>'+esc(Object.values(i.options).join(' · '))+'</p><p>Quantidade: '+i.quantity+'</p><strong>'+cash(i.quantity*i.price)+'</strong></article>'}).join('')+'</div><h2>Subtotal: '+cash(cart.reduce((s,i)=>s+i.price*i.quantity,0))+'</h2><button id="edit-cart" class="buy-button">EDITAR CARRINHO</button> <a href="/catalogo.html">Continuar comprando</a>';document.getElementById('edit-cart').onclick=openCart;
}else if(root){let page=1;const pageSize=24;const category=params.get('categoria')||'';let query=params.get('q')||'';let order='default';const isFavorites=location.pathname==='/favoritos.html';const title=isFavorites?'Meus favoritos':category?decodeURIComponent(category).replaceAll('/',' ').replaceAll('-',' ').trim().toUpperCase():'Todos os produtos';root.innerHTML='<nav class="store-crumbs"><a href="/">G SUPLEMENTOS</a><span>›</span><span>'+esc(title)+'</span></nav><div class="store-list-head"><h1>'+esc(title)+'</h1><small id="result-count"></small></div><div class="store-filter"><input id="catalog-query" type="search" aria-label="Pesquisar produtos" placeholder="O que você procura?" value="'+esc(query)+'"><select id="catalog-sort" aria-label="Ordenar produtos"><option value="default">Mais relevantes</option><option value="low">Menor preço</option><option value="high">Maior preço</option><option value="name">Nome A–Z</option></select></div><div class="store-products" id="catalog-results"></div><div class="store-pages" id="catalog-pages"></div>';
function render(){let rows=catalog.filter(p=>!isFavorites||favorites.includes(p.id));if(category){const cat=category.replace(/\/$/,'');const exact=rows.filter(p=>p.categoryPaths.some(x=>x.replace(/\/$/,'')===cat));rows=exact.length?exact:rows.filter(p=>clean(p.name+' '+p.category).includes(clean(cat.replaceAll('/',' ').replaceAll('-',' ').trim())))}if(query)rows=rows.filter(p=>clean(p.name+' '+p.category).includes(clean(query)));if(order==='low')rows.sort((a,b)=>(a.price??Infinity)-(b.price??Infinity));if(order==='high')rows.sort((a,b)=>(b.price??0)-(a.price??0));if(order==='name')rows.sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));const pages=Math.max(1,Math.ceil(rows.length/pageSize));page=Math.min(page,pages);document.getElementById('result-count').textContent=rows.length+' produtos';document.getElementById('catalog-results').innerHTML=rows.slice((page-1)*pageSize,page*pageSize).map(card).join('')||'<p>Nenhum produto encontrado. Experimente outro termo.</p>';document.getElementById('catalog-pages').innerHTML='<button id="prev-page" '+(page<=1?'disabled':'')+'>Anterior</button><span>'+page+' / '+pages+'</span><button id="next-page" '+(page>=pages?'disabled':'')+'>Próxima</button>';document.getElementById('prev-page').onclick=()=>{page--;render();root.scrollIntoView()};document.getElementById('next-page').onclick=()=>{page++;render();root.scrollIntoView()};wireFavorites(root)}document.getElementById('catalog-query').oninput=e=>{query=e.target.value;page=1;render()};document.getElementById('catalog-sort').onchange=e=>{order=e.target.value;page=1;render()};render();}
updateBadges();
})();
